// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { Grid, Row, Column } from 'carbon-components-react';

function App() {
  return (
    <div style={{ padding: '20px' }}>
      <h3>Default Grid (gutter=24px)</h3>
      <Grid>
        <Row>
          <Column md={4} style={{ background: '#d0f0fc', padding: '8px' }}>Col 1</Column>
          <Column md={4} style={{ background: '#d0f0fc', padding: '8px' }}>Col 2</Column>
          <Column md={4} style={{ background: '#d0f0fc', padding: '8px' }}>Col 3</Column>
        </Row>
      </Grid>

      <h3 style={{ marginTop: '40px' }}>Narrow Grid (gutter=16px) via <code>narrow</code> prop</h3>
      <Grid narrow>
        <Row>
          <Column md={4} style={{ background: '#d0f0fc', padding: '8px' }}>Col 1</Column>
          <Column md={4} style={{ background: '#d0f0fc', padding: '8px' }}>Col 2</Column>
          <Column md={4} style={{ background: '#d0f0fc', padding: '8px' }}>Col 3</Column>
        </Row>
      </Grid>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
